use std::sync::{Arc,Mutex};use serde_json::{json,Value};
use crate::{semantic::SemanticService,workspace_worker::Workers,RagState};
type R<T>=Result<T,String>;
fn select(rows:&[Value],limit:usize,threshold:f64)->Vec<Value>{let mut out=Vec::new();let mut remaining=24000usize;for result in rows{if result["score"].as_f64().is_none_or(|score|!score.is_finite()||score<threshold){continue}let title=result["title"].as_str().unwrap_or("");for chunk in result["chunks"].as_array().into_iter().flatten(){let text=chunk["text"].as_str().unwrap_or("");let overhead=title.chars().take(150).collect::<String>().len()+40;if text.trim().is_empty()||remaining<=overhead+100{continue}remaining-=overhead;let mut end=text.len().min(remaining);while !text.is_char_boundary(end){end-=1}let excerpt=&text[..end];if excerpt.trim().is_empty(){continue}if let Some(start)=chunk["start"].as_u64(){out.push(json!({"id":result["id"],"title":title,"text":excerpt,"start":start,"end":start+excerpt.chars().count() as u64,"field":chunk["field"]}));remaining-=end}if out.len()>=limit{return out}}}out}
fn accept(answer:&mut Option<String>,sources:&mut Vec<Value>,proposed:Vec<Value>,value:Result<String,String>)->bool{if let Ok(v)=value{*answer=Some(v);*sources=proposed;true}else{false}}
pub fn search(workers:&Workers,id:&str,session:&str,semantic:&SemanticService,rag:&Arc<Mutex<RagState>>,body:&Value)->R<Value>{
 let query=body["query"].as_str().filter(|q|!q.is_empty()&&q.len()<=1000).ok_or("Некорректный запрос")?;let agentic=match body.get("agentic"){None=>false,Some(Value::Bool(v))=>*v,_=>return Err("Некорректный режим".into())};let ids=match body.get("object_ids"){None|Some(Value::Null)=>None,Some(Value::Array(v))=>Some(v.iter().map(|x|x.as_str().map(str::to_owned).ok_or("Некорректный фильтр")).collect::<Result<Vec<_>,_>>()?),_=>return Err("Некорректный фильтр".into())};
 atlas_llama_probe::set_search_deadline(std::time::Instant::now()+std::time::Duration::from_secs(150));let initial=crate::worker_models::search_session(workers,id,session,semantic,query,ids.as_deref()).map_err(|e|e.to_string())?;let revision=initial["revision"].as_str().ok_or("Ревизия недоступна")?.to_owned();let mut results=initial["results"].as_array().ok_or("Результаты недоступны")?.clone();results=crate::exclude_image_chunks(results);let mut candidates=results.clone();let mut answer=None;let mut error=None;let mut sources=Vec::new();
 let generator={let guard=rag.lock().map_err(|_|"Модель недоступна")?;match &*guard{RagState::Ready(g)=>Some(g.clone()),_=>None}};let Some(generator)=generator else{return Err("Модель ответа не загружена".into())};let generator=generator.acquire()?;
 if !agentic{let first=select(&candidates,5,0.70);if !first.is_empty(){let generated=generator.answer(query,&first);if !accept(&mut answer,&mut sources,first,generated){error=Some("Не удалось сформировать ответ. Найденные фрагменты доступны ниже.")}}}
 let mut retry=agentic||sources.is_empty();if !retry{if let Some(a)=answer.as_ref(){retry=match generator.answer_quality(query,a,&sources){Ok(v)=>v!="sufficient",Err(_)=>{error=Some("Не удалось проверить полноту ответа");false}}}}
 if retry&&!agentic{let expanded=select(&candidates,8,0.65);if expanded.len()>sources.len(){let generated=generator.answer(query,&expanded);if accept(&mut answer,&mut sources,expanded,generated){retry=match generator.answer_quality(query,answer.as_ref().unwrap(),&sources){Ok(v)=>v!="sufficient",Err(_)=>{error=Some("Не удалось проверить полноту ответа");false}}}else{error=Some("Не удалось расширить ответ; показан предыдущий результат");retry=false}}}
 if retry&&error.is_none(){let questions=match generator.search_questions(query,agentic){Ok(v)=>v,Err(_)=>{error=Some("Не удалось подготовить дополнительные поисковые запросы");vec![]}};let mut groups=Vec::new();for q in questions.iter().take(if agentic{3}else{2}){match crate::worker_models::search_session(workers,id,session,semantic,q,ids.as_deref()){Ok(v) if v["revision"].as_str()==Some(&revision)=>groups.push(crate::exclude_image_chunks(v["results"].as_array().cloned().unwrap_or_default()).into_iter().filter(|r|r["score"].as_f64().is_some_and(|x|x.is_finite()&&x>=0.65)).take(4).collect::<Vec<_>>()),_=>{error=Some("Не удалось выполнить дополнительный поиск");break}}}candidates=crate::merge_agentic(&groups,candidates);let mut visible=std::collections::HashSet::new();for r in &results{for c in r["chunks"].as_array().into_iter().flatten(){visible.insert((r["id"].to_string(),c["field"].to_string(),c["start"].to_string(),c["end"].to_string()));}}let count=results.len();for r in &candidates{if results.len()>=count+12{break}if r["chunks"].as_array().is_some_and(|cs|cs.iter().any(|c|visible.insert((r["id"].to_string(),c["field"].to_string(),c["start"].to_string(),c["end"].to_string())))){results.push(r.clone())}}
  let proposed=select(&candidates,8,0.65);if !proposed.is_empty()&&error.is_none(){let generated=generator.answer(query,&proposed);if !accept(&mut answer,&mut sources,proposed,generated){error=Some("Не удалось улучшить ответ; показан предыдущий результат")}else{match generator.answer_quality(query,answer.as_ref().unwrap(),&sources){Ok(v) if v!="sufficient"=>error=Some("Ответ может быть неполным: проверьте найденные фрагменты"),Err(_)=>error=Some("Не удалось проверить полноту ответа"),_=>{}}}}}
 if sources.is_empty()&&error.is_none(){answer=Some("Не найдено достаточно близких фрагментов".into())}drop(generator);
 if error.is_none()||answer.is_some(){let result=workers.request_session(id,session,&json!({"action":"history-save","query":query,"mode":"rag","object_ids":ids,"results":results,"revision":revision,"answer":answer,"sources":sources,"error":error,"agentic":agentic})).map_err(|e|e.to_string())?;if let Some(e)=result["error"].as_str(){return Err(e.into())}}
 Ok(json!({"answer":answer,"error":error,"results":results,"sources":sources}))
}
